SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$QDC relationship: s1.6(5), printed p.15$q$, 'APPLICATION', $q$(5) All parts of the Queensland Development Code MP1.1 and MP1.2 including performance criteria 4, 5, 7, 8 and 9 and the corresponding acceptable solutions apply to relevant development pursuant to Section 6 of the Building Regulation 2021 (unless a relevant alternative provision applies.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
