SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$QDC relationship: Table 5.6.1, printed p.103$q$, 'APPLICATION', $q$Editor's note--Some of the acceptable outcomes for detached houses in the Low density residential code are alternative provisions to the Queensland Development Code.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$QDC relationship: Table 6.2.1.3.1 'Dwelling houses' heading (PO4-PO5)$q$, 'APPLICATION', $q$Editor's note--The following acceptable outcomes are alternative provisions for the purposes of the Queensland Development Code.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$QDC relationship: Council web page (COUNCIL_FACTSHEET)$q$, 'APPLICATION', $q$The Redland City Plan can identify alternative and/or additional requirements where a more locally specific outcome is sought. In these cases, City Plan will override the QDC.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/Planning-building-and-development/What-approvals-do-I-need/Queensland-Development-Code$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def Administrative definitions (adoption)$q$, 'DEFINITION', $q$Note--As prescribed by section 8(1) of the Planning Regulation the administrative terms and their definitions are located in schedule 4 columns 1 and 2 of the Regulation.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def setback$q$, 'DEFINITION', $q$setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 4 (current as at 11 Sept 2026), adopted via SC1.2$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def site cover$q$, 'DEFINITION', $q$site cover, of development, means the portion of the site, expressed as a percentage, that will be covered by a building or structure, measured to its outermost projection, after the development is carried out, other than a building or structure, or part of a building or structure, that is-- (a) in a landscaped or open space area, including, for example, a gazebo or shade structure; or (b) a basement that is completely below ground level and used for car parking; or (c) the eaves of a building; or (d) a sun shade.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 4$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def building height$q$, 'DEFINITION', $q$building height, of a building, means-- (a) the vertical distance, measured in metres, between the ground level of the building and the highest point on the roof of the building, other than a point that is part of an aerial, chimney, flagpole or load-bearing antenna; or (b) the number of storeys in the building above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 4$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def outermost projection$q$, 'DEFINITION', $q$outermost projection, of a building or structure, means the outermost part of the building or structure, other than a part that is-- (a) a retractable blind; or (b) a fixed screen; or (c) a rainwater fitting; or (d) an ornamental attachment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 4$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def site$q$, 'DEFINITION', $q$site, of development, means the land that the development is to be carried out on.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 4$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def ground level$q$, 'DEFINITION', $q$ground level means-- (a) the level of the natural ground; or (b) if the level of the natural ground has changed, the level as lawfully changed.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 24 (Dictionary)$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def storey$q$, 'DEFINITION', $q$storey-- (a) means a space within a building between 2 floor levels, or a floor level and a ceiling or roof, other than-- (i) a space containing only a lift shaft, stairway or meter room; or (ii) a space containing only a bathroom, shower room, laundry, toilet or other sanitary compartment; or (iii) a space containing only a combination of the things stated in subparagraph (i) or (ii); or (iv) a basement with a ceiling that is not more than 1m above ground level; and (b) includes-- (i) a mezzanine; and (ii) a roofed structured that is on, or part of, a rooftop, if the structure does not only accommodate building plant and equipment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 24 (sch 4 cross-refers)$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def domestic outbuilding$q$, 'DEFINITION', $q$domestic outbuilding means a non-habitable class 10a building that is-- (a) a shed, garage or carport; and (b) ancillary to a residential use carried out on the premises where the building is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 24$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def dwelling house$q$, 'DEFINITION', $q$dwelling house means a residential use of premises involving-- (a) 1 dwelling and any domestic outbuildings associated with the dwelling; or (b) 2 dwellings, 1 of which is a secondary dwelling, and any domestic outbuildings associated with either dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Planning Regulation 2017 sch 24 (sch 3 cross-refers); adopted by SC1.1$q$, NULL, $q$https://www.legislation.qld.gov.au/view/pdf/inforce/current/sl-2017-0078$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def Building footprint (scheme-specific)$q$, 'DEFINITION', $q$The two-dimensional extent of built development, including balconies, covered private outdoor living areas and enclosed spaces but excluding the part of a building or structure that is: - an eave or a roof; or - a sunhood or the like attached to the wall of a building or structure to provide shade or shelter to the wall.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Table SC1.2.1$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def Low-rise (scheme-specific)$q$, 'DEFINITION', $q$One to two storeys.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Table SC1.2.1$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def Rear lot (scheme-specific)$q$, 'DEFINITION', $q$A lot which has access to a road by means only of an access strip which forms part of the lot, or by means only of an easement over adjoining land.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Table SC1.2.1$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$def frontage / secondary frontage / wall height / front building line$q$, 'DEFINITION', $q$NOT DEFINED in City Plan v14 Table SC1.2.1 or in Planning Regulation 2017 sch 4 as checked; 'front building line' is used in LDR3 AO15.1 without definition.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$n/a$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$LOA Table 5.4.1 Dwelling house (MCU) / Low density residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house | Accepted | If not accepted subject to requirements | Accepted subject to requirements | Editor's note--Dwelling houses not complying with the relevant acceptable outcomes will require a concurrence agency referral to Council under Schedule 9 of the Regulation. | If in precincts LDR1, LDR2, LDR3, LDR4 or LDR5. | Low density residential zone code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Level: Accepted; Accepted subject to requirements if in precincts LDR1-LDR5. Conditions: Accepted subject to requirements (LDR zone code) if in precincts LDR1, LDR2, LDR3, LDR4 or LDR5; otherwise Accepted$q$, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$LOA Table 5.6.1, printed p.103 Building work / Low density residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Accepted subject to requirements ... If: (1) a dwelling house in precincts LDR1, LDR2, LDR3, LDR4 or LDR5; or (2) a dual occupancy in precinct LDR5; or (3) Building work associated with a dwelling house in LDR5; or (4) Building work associated with a dual occupancy in LDR5. Editor's note: Building work is defined by the Building Act 1975. | Low density residential zone code ... Accepted development Any other building work not listed in this table.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Level: Accepted; Accepted subject to requirements for listed cases. Conditions: (1) dwelling house in LDR1-LDR5; (2) dual occupancy in LDR5; (3)/(4) building work associated with a dwelling house or dual occupancy in LDR5$q$, NULL);
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$LOA Table 5.6.1 Building work (non-compliance consequence) / Low density residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Editor's note--Building work for dwelling houses not complying with the relevant acceptable outcomes will require a concurrence agency referral to Council under Schedule 9 of the Regulation, or trigger a code assessable Building Work Assessable Against the Planning Scheme application. Refer to the editor's notes in Table 6.2.1.3.1 for further clarification.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Level: Concurrence referral or code assessment. Conditions: Depends on whether the failed AO is an alternative provision$q$, NULL);
