SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO4 / AO4.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO4 Development in precinct LDR2 park residential maintains the amenity of adjoining premises by ensuring substantial separation between dwelling houses on adjoining land, and between dwelling houses and the street frontage. AO4.1 In precinct LDR2 park residential, dwelling houses (including outbuildings) are set back 10m from a road frontage and 10m from a side or rear boundary.$q$, 'VERIFIED_VERBATIM', $q$printed p.122 (PDF p.126), heading 'Dwelling houses'$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$No setback-specific measurement rule in the code; 'setback' is a Planning Regulation 2017 sch 4 administrative term adopted by the scheme (SC1.2): shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary.$q$, $q$ldr2_road_setback_10m$q$);
