SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO6 / AO6.1$q$, 'ACCEPTABLE_OUTCOME', $q$Dwelling houses in precincts LDR1: Large lot precinct and LDR2: Park residential precinct. Editor's note--A number of the following acceptable outcomes are alternative provisions for the purposes of the Queensland Development Code. PO6 Buildings have a limited site cover in order to maintain an open, low density character AO6.1 Site cover does not exceed 30% of site area.$q$, 'VERIFIED_VERBATIM', $q$printed p.123 (PDF p.127)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Site cover per Planning Regulation 2017 sch 4: portion of the site covered by a building or structure measured to its outermost projection, excluding structures in landscaped/open space areas (e.g. gazebo or shade structure), basements fully below ground for parking, eaves, sun shades.$q$, $q$ldr1_ldr2_site_cover_30pct$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr1_ldr2_site_cover_30pct", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SITE_COVER", "title": "Table 6.2.1.3.1, PO6 / AO6.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 30, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR1"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR2"}], "subjects": ["CLASS_1"], "sources": [{"key": "ldr1_ldr2_site_cover_30pct", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"site cover\", \"operator\": \"<=\", \"value\": 30, \"unit\": \"%\", \"conditions\": [\"precinct LDR1 or LDR2\", \"dwelling houses\"], \"exceptions\": [], \"formula_text\": null}\nLocal plan: Precincts LDR1 large lot and LDR2 park residential (zone precincts)\nStructure scope 'buildings (dwelling houses and associated buildings)' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Heading note says 'A number of the following' are alternative provisions; AO6.1 is the only AO under that heading and it relates to site cover, a matter s.33 Building Act allows schemes to vary, so treated as YES. Council's QDC web pages likewise describe 'alternative site cover' in LDR precincts (COUNCIL_FACTSHEET-level corroboration)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr1_ldr2_site_cover_30pct@2025-11-10$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$RCC.ldr1_ldr2_site_cover_30pct@2025-11-10$q$, $q$QDC12.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$RCC.ldr1_ldr2_site_cover_30pct@2025-11-10$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO7 / AO7.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO7 Development is set back from a property boundary adjoining a revetment wall to: (1) Reduce the risk to new structures from the construction, maintenance, structural deterioration or failure of revetment walls; (2) Maintain the structural stability of revetment walls. AO7.1 Development is set back 9m from the property boundary adjoining a revetment wall. Editor's note - This acceptable outcome is not an alternative provision for the purposes of the Queensland Development Code. Where building work for a dwelling house/dual occupancy does not meet the acceptable solution, a code assessable Building Works Assessable Against the Planning Scheme application will be triggered.$q$, 'VERIFIED_VERBATIM', $q$printed p.123 (PDF p.127)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$No setback-specific measurement rule in the code; 'setback' is a Planning Regulation 2017 sch 4 administrative term adopted by the scheme (SC1.2): shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. Editor's note also references '9.0m from the top of the revetment wall'.$q$, $q$ldr5_revetment_wall_setback_9m$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr5_revetment_wall_setback_9m", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SETBACK.REAR", "title": "Table 6.2.1.3.1, PO7 / AO7.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 9, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR5"}], "subjects": ["CLASS_1"], "sources": [{"key": "ldr5_revetment_wall_setback_9m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"setback from boundary adjoining revetment wall\", \"operator\": \">=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"precinct LDR5\", \"boundary adjoins a revetment wall\"], \"exceptions\": [\"Editor's note: development at or beyond 9.0m from top of revetment wall, or placing not more than 2.0kPa net positive load on the wall, is unlikely to cause damage\"], \"formula_text\": null}\nLot conditions (not encoded): property boundary adjoining a revetment wall\nLocal plan: Precinct LDR5 Canal and Lakeside Estates (zone precinct)\nStructure scope 'development (dwelling houses and dual occupancies, incl. associated building work)' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Planning assessment benchmark, not QDC alternative: non-compliance triggers code assessable building work against the planning scheme (Table 5.6.1 makes building work associated with a dwelling house in LDR5 accepted subject to requirements). Applies to pools/retaining walls as structures (PO7 note mentions pools). Proposed amendment 02/25 would expressly include swimming pools and excavation/filling (not in force)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr5_revetment_wall_setback_9m@2025-11-10$q$;
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO8 / AO8.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO8 Development is set back from property boundaries to provide unimpeded access to allow for the maintenance of revetment walls. AO8.1 Development is setback a minimum of 2m from the property boundary adjoining a revetment wall, to allow for maintenance of the revetment wall to be undertaken from the land.$q$, 'VERIFIED_VERBATIM', $q$printed p.123 (PDF p.127)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$No setback-specific measurement rule in the code; 'setback' is a Planning Regulation 2017 sch 4 administrative term adopted by the scheme (SC1.2): shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary.$q$, $q$ldr5_revetment_maintenance_setback_2m$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr5_revetment_maintenance_setback_2m", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SETBACK.REAR", "title": "Table 6.2.1.3.1, PO8 / AO8.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 2, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR5"}], "subjects": ["ANY"], "sources": [{"key": "ldr5_revetment_maintenance_setback_2m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"setback from boundary adjoining revetment wall (maintenance access)\", \"operator\": \">=\", \"value\": 2, \"unit\": \"m\", \"conditions\": [\"precinct LDR5\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): property boundary adjoining a revetment wall\nLocal plan: Precinct LDR5 Canal and Lakeside Estates (zone precinct)\nStructure scope 'development' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Editor's note: 'The above acceptable outcomes (AO8.1 and AO8.2) are not alternative provisions for the purposes of the Queensland Development Code.' and 'They do not override PO7/ AO7.1 or PO9/AO9.1'. Amendment 02/25 consultation proposed 2.5m; council reportedly resolved (July 2026) to retain 2m - not yet in force."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr5_revetment_maintenance_setback_2m@2025-11-10$q$;
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO8 / AO8.2$q$, 'ACCEPTABLE_OUTCOME', $q$AO8.2 Development provides a minimum 1m side access along the full length of one side of the property to provide a clear path between the road frontage and the revetment wall to allow for access for maintenance of the revetment wall.$q$, 'VERIFIED_VERBATIM', $q$printed p.123 (PDF p.127)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Clear path width along one side of property from road frontage to revetment wall.$q$, $q$ldr5_side_access_1m$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr5_side_access_1m", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SETBACK.SIDE", "title": "Table 6.2.1.3.1, PO8 / AO8.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 1, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR5"}], "subjects": ["ANY"], "sources": [{"key": "ldr5_side_access_1m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"clear side access along one side boundary (full length)\", \"operator\": \">=\", \"value\": 1, \"unit\": \"m\", \"conditions\": [\"precinct LDR5\", \"one side only\"], \"exceptions\": [], \"formula_text\": null}\nLocal plan: Precinct LDR5 Canal and Lakeside Estates (zone precinct)\nStructure scope 'development' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not an alternative provision (editor's note). Effectively requires one side boundary to be kept clear of structures for 1m - relevant to sheds/carports built to boundary in LDR5."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr5_side_access_1m@2025-11-10$q$;
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO9 / AO9.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO9 Development maintains the amenity of adjoining premises and the local area by ensuring that no development (including domestic outbuildings and other roofed structures, but excluding in-ground swimming pools) is established closer to the canal/lake than existing dwellings on adjoining sites. Note - for PO9, `dwelling' is taken to include structures which are attached to the dwelling, but not detached structures on the same lot. AO9.1 Development (including domestic outbuildings and other roofed structures, but excluding in-ground swimming pools) is setback a minimum of 9m from the property boundary adjoining a canal or lake. Editor's note - This acceptable outcome is an alternative provision for the purposes of the Queensland Development Code. Building works for a dwelling house/dual occupancy not complying with this acceptable outcome will require a concurrence agency referral to Council under schedule 9 of the Regulation.$q$, 'VERIFIED_VERBATIM', $q$printed p.123-124 (PDF p.127-128)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$No setback-specific measurement rule in the code; 'setback' is a Planning Regulation 2017 sch 4 administrative term adopted by the scheme (SC1.2): shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. PO9 alternative test uses line of adjoining dwellings (Figures 6.2.1.2.6-6.2.1.2.8; centre of site delineates change in line).$q$, $q$ldr5_canal_lake_setback_9m$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr5_canal_lake_setback_9m", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SETBACK.REAR", "title": "Table 6.2.1.3.1, PO9 / AO9.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 9, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR5"}], "subjects": ["POOL", "CLASS_10A"], "sources": [{"key": "ldr5_canal_lake_setback_9m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"setback from boundary adjoining canal or lake\", \"operator\": \">=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"precinct LDR5\", \"includes domestic outbuildings and other roofed structures\"], \"exceptions\": [\"in-ground swimming pools excluded\"], \"formula_text\": null}\nLot conditions (not encoded): property boundary adjoining a canal or lake\nLocal plan: Precinct LDR5 Canal and Lakeside Estates (zone precinct)\nStructure scope 'development including domestic outbuildings and other roofed structures, excluding in-ground swimming pools' mapped by keyword to ['POOL', 'CLASS_10A']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Express alternative provision (quoted). Above-ground pools and roofed decks/patios/pergolas fall within 'development... other roofed structures' (unroofed decks: UNKNOWN - manual review)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr5_canal_lake_setback_9m@2025-11-10$q$;
