SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO11 / AO11.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO11 Buildings have a limited site cover in order to maintain an open, low density character. AO11.1 Site cover does not exceed 30% of site area. Editor's note - This acceptable outcome is an alternative provision for the purposes of the Queensland Development Code. Building works for a dwelling house not complying with this acceptable outcome will require a concurrence agency referral to Council under schedule 9 of the Regulation.$q$, 'VERIFIED_VERBATIM', $q$printed p.126 (PDF p.130)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Site cover per Planning Regulation 2017 sch 4 (see definitions).$q$, $q$ldr3_site_cover_30pct$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr3_site_cover_30pct", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SITE_COVER", "title": "Table 6.2.1.3.1, PO11 / AO11.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 30, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR3"}], "subjects": ["CLASS_1"], "sources": [{"key": "ldr3_site_cover_30pct", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"site cover\", \"operator\": \"<=\", \"value\": 30, \"unit\": \"%\", \"conditions\": [\"precinct LDR3 Point Lookout (North Stradbroke Island)\"], \"exceptions\": [], \"formula_text\": null}\nLocal plan: Precinct LDR3 Point Lookout residential (zone precinct)\nStructure scope 'buildings (dwelling houses)' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Express alternative provision."}$q$::jsonb);
