INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$RCC.ldr3_site_cover_30pct@2025-11-10$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO12 / AO12.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO12 Development takes the form of a series of small scale building components which reduce the overall bulk and obtrusiveness of buildings. AO12.1 The size of any single detached building component does not exceed: (1) 150m2 when the building height is not more than 4.5m above ground level; or (2) 140m2 when the building height is over 4.5m above ground level. Editor's note - This acceptable outcome is an alternative provision for the purposes of the Queensland Development Code. Building works for a dwelling house not complying with this acceptable outcome will require a concurrence agency referral to Council under schedule 9 of the Regulation.$q$, 'VERIFIED_VERBATIM', $q$printed p.126 (PDF p.130)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$'Size' basis (GFA vs footprint) not defined in the AO - manual review.$q$, $q$ldr3_building_component_size$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr3_building_component_size", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "OUTBUILDING.SIZE", "title": "Table 6.2.1.3.1, PO12 / AO12.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": {"op": "unencoded", "text": "<=150 m2 if building height <=4.5m above ground level; <=140 m2 if building height >4.5m above ground level", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m2", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR3"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "ldr3_building_component_size", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"size of single detached building component\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m2\", \"conditions\": [\"precinct LDR3\"], \"exceptions\": [], \"formula_text\": \"<=150 m2 if building height <=4.5m above ground level; <=140 m2 if building height >4.5m above ground level\"}\nLocal plan: Precinct LDR3 Point Lookout residential (zone precinct)\nStructure scope 'any single detached building component (dwelling house and detached outbuildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Express alternative provision."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr3_building_component_size@2025-11-10$q$;
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO12 / AO12.2$q$, 'ACCEPTABLE_OUTCOME', $q$AO12.2 Each detached building component is separated by 4m to the outermost projection of any other detached building on the site. Figure 6.2.1.3.1 illustrates. Editor's note - This acceptable outcome is not an alternative provision for the purposes of the Queensland Development Code. Where building work for a dwelling house does not meet the acceptable solution, a code assessable Building Works Assessable Against the Planning Scheme application will be triggered.$q$, 'VERIFIED_VERBATIM', $q$printed p.126-127 (PDF p.130-131)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Measured to the outermost projection of any other detached building on the site.$q$, $q$ldr3_building_component_separation_4m$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr3_building_component_separation_4m", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "SEPARATION.BUILDINGS", "title": "Table 6.2.1.3.1, PO12 / AO12.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SEPARATION", "operator": ">=", "value": 4, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR3"}], "subjects": ["ANY"], "sources": [{"key": "ldr3_building_component_separation_4m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"separation between detached building components\", \"operator\": \">=\", \"value\": 4, \"unit\": \"m\", \"conditions\": [\"precinct LDR3\"], \"exceptions\": [], \"formula_text\": null}\nLocal plan: Precinct LDR3 Point Lookout residential (zone precinct)\nStructure scope 'detached building components' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Editor's note sits at top of p.127 immediately after AO12.2 (page image checked: notes in this table follow the AO they refer to)."}$q$::jsonb);
