SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO13 / AO13.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO13 The height of a building does not unduly: (1) overshadow adjoining houses; and (2) obstruct the outlook from adjoining lots. AO13.1 For slopes up to 15%, building height is 8.5m, except for roofs or pergolas covering decks. These may extend to 10m above ground level, providing: (1) they cover an area of no more than 10m2; (2) there is only one such covered areas on each detached building component on the site; and (3) the covered area is not enclosed by walls. Editor's note--This provision establishes an alternative solution to the Queensland Development Code for buildings on slopes <15%. For buildings on slopes >15%, the acceptable solution under the Queensland Development Code applies.$q$, 'VERIFIED_VERBATIM', $q$printed p.127 (PDF p.131)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, $q$Building height per Planning Regulation 2017 sch 4 (vertical distance from ground level to highest point of roof, excluding aerial, chimney, flagpole or load-bearing antenna).$q$, $q$ldr3_building_height_8_5m$q$);
SELECT define_rule($q${"rule_id": "RCC.ldr3_building_height_8_5m", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.1.3.1, PO13 / AO13.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 8.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "PRECINCT", "precinct": "RCC:LOW_DENSITY_RESIDENTIAL/LDR3"}], "subjects": ["OUTDOOR_STRUCTURE"], "sources": [{"key": "ldr3_building_height_8_5m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"building height\", \"operator\": \"<=\", \"value\": 8.5, \"unit\": \"m\", \"conditions\": [\"precinct LDR3\", \"slope up to 15%\"], \"exceptions\": [\"roofs or pergolas covering decks may extend to 10m above ground level if <=10m2, only one per detached building component, not enclosed by walls\"], \"formula_text\": null}\nLot conditions (not encoded): slope up to 15%\nLocal plan: Precinct LDR3 Point Lookout residential (zone precinct)\nStructure scope 'buildings; roofs or pergolas covering decks' mapped by keyword to ['OUTDOOR_STRUCTURE']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Note wording 'alternative solution' (not 'alternative provision'); slopes >15% revert to QDC. Text inconsistency '<15%' vs 'up to 15%' - exactly 15% ambiguous."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr3_building_height_8_5m@2025-11-10$q$;
