SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO14 / AO14.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO14 Buildings are stepped to mirror the slope of the land and do not result in buildings established substantially above ground level. AO14.1 Floor level (including decks and verandahs) does not exceed a height of: (1) 3m above ground level for the first level of the building; and (2) 5.1m above ground level for the uppermost level of the building. Figure 6.2.1.3.2 illustrates. Editor's note - This acceptable outcome is not an alternative provisions for the purposes of the Queensland Development Code. Where building work for a dwelling house does not meet the acceptable solution, a code assessable Building Works Assessable Against the Planning Scheme application will be triggered.$q$, 'VERIFIED_VERBATIM', $q$printed p.127 (PDF p.131) - verified against page image$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, $q$ldr3_floor_level_height$q$);
