UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr3_floor_level_height@2025-11-10$q$;
SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO10 / AO10.1-AO10.3$q$, 'ACCEPTABLE_OUTCOME', $q$PO10 Development minimises the extent of earthworks. AO10.1 Excavation and fill is limited to: (1) maximum cut of 1.2m below ground level; and (2) maximum fill of 1.2m above ground level. AO10.2 Retaining walls have a maximum height of 600mm at the street frontage. AO10.3 Benched areas for driveways and landscape areas do not exceed 25m2. Editor's note - The above acceptable outcomes (AO10.1, 10.2 and 10.3) are not alternative provisions for the purposes of the Queensland Development Code. Where building work for a dwelling house does not meet the acceptable solution/s, a code assessable Building Works Assessable Against the Planning Scheme application will be triggered.$q$, 'VERIFIED_VERBATIM', $q$printed p.125-126 (PDF p.129-130)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, $q$ldr3_earthworks$q$);
