SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO15 / AO15.1$q$, 'ACCEPTABLE_OUTCOME', $q$PO15 Fences do not dominate the street frontage. AO15.1 Fences: (1) are not established beyond the front building line; (2) have a maximum height of 1.5m; and (3) are of open timber construction. Figure 6.2.1.3.3 illustrates. Editor's note - This acceptable outcome is not an alternative provision for the purposes of the Queensland Development Code. Where building work for a dwelling house does not meet the acceptable solution, a code assessable Building Works Assessable Against the Planning Scheme application will be triggered.$q$, 'VERIFIED_VERBATIM', $q$printed p.127-128 (PDF p.131-132)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, $q$ldr3_fences$q$);
