SELECT define_provision($q$RCC_CITY_PLAN_2018@2025-11-10$q$, $q$Table 6.2.1.3.1, PO16 / AO16.1$q$, 'ACCEPTABLE_OUTCOME', $q$AO16.1 Buildings: (1) use light weight finishes such as timber and fibre cement, except for retaining walls and major structural elements; (2) are provided with eaves at least 600mm wide; (3) incorporate verandahs or decks; and (4) use non reflective sheet material for roofing. Editor's note - This acceptable outcome is not an alternative provision for the purposes of the Queensland Development Code. ...$q$, 'VERIFIED_VERBATIM', $q$printed p.128 (PDF p.132)$q$, NULL, $q$Low density residential zone code$q$, NULL, $q$https://www.redland.qld.gov.au/files/assets/public/v/7/planning-and-development/documents/redland-city-plan-documents/redland-city-plan-version-14/redland-city-plan-version-14-updated-23-september-2026-with-changes-to-sc-5.pdf$q$, NULL, $q$ldr3_architectural_style$q$);
