SELECT define_rule($q${"rule_id": "RCC.ldr_general_no_alt_provisions", "instrument_version": "RCC_CITY_PLAN_2018@2025-11-10", "topic": "OTHER", "title": "Table 5.4.1 / Table 5.6.1 / Table 6.2.1.3.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "No City Plan siting benchmarks for dwelling houses/outbuildings; QDC MP1.1/MP1.2 (now QHC) acceptable solutions apply via Building Regulation 2021", "extracted_value": null, "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-11-10", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "REDLAND"}, {"level": "ZONE", "zone": "RCC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "ldr_general_no_alt_provisions", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"applicable siting rules\", \"operator\": \"=\", \"value\": null, \"unit\": null, \"conditions\": [\"LDR zone land not within any precinct\"], \"exceptions\": [], \"formula_text\": \"No City Plan siting benchmarks for dwelling houses/outbuildings; QDC MP1.1/MP1.2 (now QHC) acceptable solutions apply via Building Regulation 2021\"}\nStructure scope 'dwelling house and Class 10a outside precincts LDR1-LDR5' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Key engine rule: in the general LDR zone (no precinct) and in LMDR, MDR, character residential, tourist accommodation, environmental management, emerging community and rural zones, dwelling houses are 'Accepted' with no requirements and no City Plan alternative provisions exist (s.1.6(5): QDC MP1.1/MP1.2 apply 'unless a relevant alternative provision applies'). Use state QHC values there."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$RCC.ldr_general_no_alt_provisions@2025-11-10$q$;

INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$REDLAND$q$, $q$RCC_CITY_PLAN_2018$q$, 'MEDIUM', $q$QHC transition: City Plan v14 alternative provisions reference the QDC (MP1.1/MP1.2) only. Whether/how they continue to operate as alternative provisions against the QHC (QDC Parts 1.1/1.2 from 1 Sept 2026) depends on Building Act/Regulation transitional provisions - not addressed in the scheme; needs state-level confirmation.$q$);
